function validate([n, edges, labels]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n must be between 1 and 100000.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must have exactly n - 1 pairs.';
  if (typeof labels !== 'string' || labels.length !== n) return 'labels must have exactly n letters.';
  if (!/^[a-z]*$/.test(labels)) return 'labels may contain only lowercase letters.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge endpoints must be node numbers from 0 to n - 1.';
    if (a === b) return 'An edge cannot join a node to itself.';
    const ra = find(a), rb = find(b);
    if (ra === rb) return 'The edges must form a tree (no cycles or repeated edges).';
    root[ra] = rb;
  }
  return null;
}

