function countSubTrees(n, edges, labels) {
  // Find each node's parent with a BFS from the root, then walk up from every node.
  const adjacent = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adjacent[a].push(b); adjacent[b].push(a); }
  const parent = new Array(n).fill(-1);
  const seen = new Array(n).fill(false);
  seen[0] = true;
  const queue = [0];
  for (let head = 0; head < queue.length; head++) {
    const v = queue[head];
    for (const w of adjacent[v]) if (!seen[w]) { seen[w] = true; parent[w] = v; queue.push(w); }
  }
  const result = new Array(n).fill(0);
  for (let v = 0; v < n; v++) {
    // v lies in the subtree of every node on its path up to the root, itself included.
    for (let u = v; u !== -1; u = parent[u]) if (labels[u] === labels[v]) result[u]++;
  }
  return result;
}

