function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2001) : int(1, 9);
  // Random node order so the root 0 can sit anywhere in the shape.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  const shape = int(0, 3);
  const edges = [];
  for (let p = 1; p < n; p++) {
    let q;
    if (shape === 0) q = p - 1;
    else if (shape === 1) q = 0;
    else if (shape === 2) q = Math.max(0, p - int(1, 3));
    else q = int(0, p - 1);
    edges.push(rand() < 0.5 ? [order[p], order[q]] : [order[q], order[p]]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const alphabet = [1, 2, 3, 26][int(0, 3)];
  let labels = '';
  for (let i = 0; i < n; i++) labels += String.fromCharCode(97 + int(0, alphabet - 1));
  return [n, edges, labels];
}
